/**
 * Reproduce: shrink window → expand window → text layout corruption.
 *
 * Hypothesis: When the user rapidly resizes, events generated by the PTY
 * at one width can arrive at the frontend AFTER a subsequent resize has
 * changed the buffer width. These "stale" events are then applied at the
 * wrong column count, corrupting layout.
 *
 * The test simulates real Tauri IPC: events arrive in chunks (max 128 per
 * chunk), and ResizeObserver fires between chunks during a drag resize.
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { TerminalBuffer } from '../buffer';
import type { TerminalEvent } from '@shared/terminal/events';

// ── Helpers ────────────────────────────────────────────────────────────────────

/** Readable snapshot: join cells of each line into a string. */
function snapshot(buf: TerminalBuffer): string[] {
  return buf.lines.map(l => l.cells.map(c => c.char).join(''));
}

/** Build TUI events like Claude/Ink does for a terminal of `w` cols.
 *  Produces a header line, a divider line, and `lineCount` lines of content. */
function makeTuiRender(w: number, lineCount: number): TerminalEvent[] {
  const ev: TerminalEvent[] = [];
  // Clear screen + home
  ev.push({ t: 'J', p: 2 });
  ev.push({ t: 'H', p: [1, 1] });

  // Header: bold yellow text
  ev.push({ t: 'm', p: [1, 38, 5, 220] }); // bold + yellow
  ev.push({ t: 'txt', p: `╭─ TUI at ${w} cols ${'─'.repeat(Math.max(0, w - 18))}` });
  ev.push({ t: 'm', p: [0] }); // reset
  ev.push({ t: 'cr' });
  ev.push({ t: 'lf' });

  // Divider
  ev.push({ t: 'txt', p: '│' + ' '.repeat(Math.max(0, w - 2)) + '│' });
  ev.push({ t: 'cr' });
  ev.push({ t: 'lf' });

  // Content lines with CHA-positioned text
  for (let i = 0; i < lineCount; i++) {
    ev.push({ t: 'G', p: 3 }); // CHA to column 3
    ev.push({ t: 'txt', p: `Line ${i + 1}: ${'.'.repeat(Math.max(0, w - 15))}` });
    ev.push({ t: 'cr' });
    ev.push({ t: 'lf' });
  }

  // Bottom border
  ev.push({ t: 'txt', p: `╰${'─'.repeat(Math.max(0, w - 2))}╯` });
  ev.push({ t: 'cr' });
  ev.push({ t: 'lf' });

  return ev;
}

/** Number of events in a TUI render. */
function eventCount(w: number, lineCount: number): number {
  return makeTuiRender(w, lineCount).length;
}

// ── Tests ──────────────────────────────────────────────────────────────────────

describe('Resize corruption — stale events at wrong width', () => {
  let buf: TerminalBuffer;

  beforeEach(() => {
    buf = new TerminalBuffer();
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 1: Simple shrink → expand, all events arrive in order
  // ──────────────────────────────────────────────────────────────────────────

  it('clean resize: shrink then expand with ordered events produces no corruption', () => {
    // Start at 100 cols
    buf.resize(100);
    buf.applyEvents(makeTuiRender(100, 3));

    // Shrink to 40
    buf.resize(40);
    buf.applyEvents(makeTuiRender(40, 5)); // more lines because narrower

    // Expand to 100
    buf.resize(100);
    buf.applyEvents(makeTuiRender(100, 3));

    const lines = snapshot(buf);
    // Debug: print all lines
    console.error('\n=== Clean resize: shrink then expand ===');
    console.error(`Total lines: ${lines.length}, cols: ${buf.cols}`);
    lines.forEach((l, i) => {
      if (l.length > buf.cols + 1) console.error(`  [${i}] OVERLONG: len=${l.length} cols=${buf.cols}`);
    });

    // Top border should show current width
    expect(lines[0]).toContain('100 cols');
    // No overlong lines (exceeding current width + margin)
    const overlong = lines.filter(l => l.length > buf.cols + 2);
    expect(overlong.length).toBe(0);
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 2: Late events — 40-col events arrive after resize to 80
  //   This is the core hypothesis: stale events processed at wrong width.
  // ──────────────────────────────────────────────────────────────────────────

  it('stale narrow events arriving after expand corrupt layout', () => {
    // Initial state: 80 cols
    buf.resize(80);
    buf.applyEvents(makeTuiRender(80, 3));

    // Shrink to 40
    buf.resize(40);
    const narrowEvents = makeTuiRender(40, 5);

    // First half of 40-col events arrive while buffer is at 40
    const mid = Math.floor(narrowEvents.length / 2);
    buf.applyEvents(narrowEvents.slice(0, mid));

    // User expands window → buffer resized
    buf.resize(80);

    // Second half of 40-col events arrive LATE — at 80 cols!
    buf.applyEvents(narrowEvents.slice(mid));

    // Now the 80-col render arrives
    buf.applyEvents(makeTuiRender(80, 3));

    const lines = snapshot(buf);

    // The final render should show 80 cols in the header
    const header = lines.find(l => l.includes('TUI at'));
    expect(header).toBeDefined();
    if (header) expect(header).toContain('80 cols');

    // Visual corruption check: are there scattered/isolated characters?
    const scattered = lines.filter(l => {
      const visible = l.replace(/\s/g, '');
      return visible.length > 0 && visible.length === 1 && l.length > 30;
    });
    // This may or may not find scattered lines depending on timing.
    // The point is to document what actually happens.
    if (scattered.length > 0) {
      console.error(`\nFOUND ${scattered.length} scattered single-char lines:`);
      scattered.slice(0, 15).forEach((l, i) => {
        console.error(`  [${i}] len=${l.length} content="${l.slice(0, 80)}"`);
      });
    }
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 3: Full chunk-split simulation with large render
  //   If a render produces > 128 events, it's split across IPC chunks.
  //   A resize between chunks causes the second chunk to be misapplied.
  // ──────────────────────────────────────────────────────────────────────────

  it('IPC chunk split: resize between chunks of same render', () => {
    buf.resize(80);
    // Generate a render that produces > 128 events
    // Each content line: CHA(1) + Text(1) + CR(1) + LF(1) = 4 events
    // 30 lines = 120 events + header (6) + footer (3) = 129 approx
    const wideRender = makeTuiRender(80, 30);
    const totalEvents = wideRender.length;
    expect(totalEvents).toBeGreaterThan(128); // ensure it would be chunked

    // Split at position that might be a chunk boundary (128 events)
    const chunkSize = 128;
    const chunk1 = wideRender.slice(0, chunkSize);
    const chunk2 = wideRender.slice(chunkSize);

    // Process chunk 1 at 80 cols
    buf.applyEvents(chunk1);

    // Simulate resize between chunks (user dragged window narrower)
    buf.resize(30);

    // Chunk 2 arrives at 30 cols instead of 80!
    buf.applyEvents(chunk2);

    const lines = snapshot(buf);

    // The output was generated for 80 cols but the second half
    // was applied at 30 cols. Content should be truncated/affected.
    const longLines = lines.filter(l => l.length > 35);
    // At 30 cols, no line should meaningfully exceed that
    if (longLines.length > 0) {
      console.error(`\nFOUND ${longLines.length} lines exceeding 30-col width:`);
      longLines.slice(0, 5).forEach((l, i) => {
        console.error(`  [${i}] len=${l.length} content="${l.slice(0, 60)}"`);
      });
    }
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 4: Realistic drag resize — many rapid resize events
  // ──────────────────────────────────────────────────────────────────────────

  it('rapid drag resize: multiple resize calls with interleaved events', () => {
    buf.resize(120);

    // Initial render at 120
    buf.applyEvents(makeTuiRender(120, 5));

    // Simulate drag: resize fires many times as user drags border
    // Each resize sends SIGWINCH, causing the app to re-render.
    // But before the re-render arrives, another resize fires.

    const widths = [100, 80, 60, 40, 50, 70, 90, 110]; // drag shrink then expand
    let currentWidth = 120;

    for (const w of widths) {
      currentWidth = w;
      buf.resize(w);
      // Simulate some events from the last resize arriving
      // (these would be for the previous width)
      const staleEvents = makeTuiRender(currentWidth, 3);
      buf.applyEvents(staleEvents);
    }

    // Final settled render
    buf.applyEvents(makeTuiRender(currentWidth, 3));

    const lines = snapshot(buf);
    // Final header should show last width
    const header = lines.find(l => l.includes('TUI at'));
    expect(header).toBeDefined();
    if (header) expect(header).toContain(`${currentWidth} cols`);

    // No single-char scattered lines
    const scattered = lines.filter(l => {
      const visible = l.replace(/\s/g, '');
      return visible.length === 1 && l.length > 20;
    });
    expect(scattered.length).toBe(0);
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 5: Events from null session should not bleed — regression check
  // ──────────────────────────────────────────────────────────────────────────

  it('resize does not leak content from previous width', () => {
    buf.resize(100);
    buf.applyEvents(makeTuiRender(100, 3));
    const lines100 = snapshot(buf);

    // Clear and start fresh at narrower width
    buf.clear();
    buf.resize(40);
    buf.applyEvents(makeTuiRender(40, 5));

    const lines40 = snapshot(buf);
    // Should not contain fragments from the 100-col render
    const has100ColHeader = lines40.some(l => l.includes('100 cols'));
    expect(has100ColHeader).toBe(false);

    // More content lines at 40 cols (the header wraps).  Compare non-blank
    // lines only — the screen model always reports scrollback + rows lines.
    const nonBlank = (ls: string[]) => ls.filter(l => l.trim().length > 0);
    expect(nonBlank(lines40).length).toBeGreaterThan(nonBlank(lines100).length);
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 6: CUP positioning at edge of old width
  //   When expanding, CUP commands from old render should not position
  //   cursor beyond the old content bounds.
  // ──────────────────────────────────────────────────────────────────────────

  it('CHA positioning within bounds after resize', () => {
    buf.resize(40);
    buf.write('A'.repeat(39));
    buf.resize(80);

    // Position cursor at column 50 and write — should stay within bounds
    buf.applyEvents([
      { t: 'G', p: 50 },        // CHA to col 50
      { t: 'txt', p: 'Hello' }, // write at col 50
    ]);

    const line = snapshot(buf)[0];
    // "Hello" should appear starting at col 49 (0-indexed col 50 → index 49)
    const helloPos = line.indexOf('Hello');
    expect(helloPos).toBe(49);
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 7: CUP from stale render exceeding current width is clamped
  // ──────────────────────────────────────────────────────────────────────────

  it('CUP column is clamped to current cols after shrink', () => {
    buf.resize(80);
    // CUP to row 1, col 60 — valid at 80 cols
    buf.applyEvents([
      { t: 'H', p: [1, 60] },
      { t: 'txt', p: 'X' },
    ]);

    buf.resize(40);
    // CUP to row 5, col 60 — was valid at 80, now exceeds 40
    // Should be clamped to 39 (cols - 1)
    buf.applyEvents([
      { t: 'H', p: [5, 60] },
      { t: 'txt', p: 'Y' },
    ]);

    // The 'Y' should be at column 39 (0-indexed), row 4 (0-indexed)
    const lines = snapshot(buf);
    const line4 = lines[4];
    expect(line4).toBeDefined();
    const yPos = line4.indexOf('Y');
    expect(yPos).toBe(39); // clamped from 59 to 39
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 8: Bare CHA (no params) — regression test for \x1b[G bug
  //   The Rust parser produces Cha(0) for bare \x1b[G (no param).
  //   If applyEvents doesn't default 0→1, cx becomes -1 and the first
  //   character after \x1b[G is written to cells[-1] (lost!).
  // ──────────────────────────────────────────────────────────────────────────

  it('bare CHA \\x1b[G moves to first column, not -1', () => {
    buf.resize(80);
    // Write some content to establish cursor position
    buf.applyEvents([
      { t: 'txt', p: 'AAAAABBBBBCCCCC' }, // cx = 15
    ]);

    // Bare \x1b[G — Rust parser produces Cha(0)
    buf.applyEvents([
      { t: 'G', p: 0 },       // CHA with 0 → should go to column 1 (cx=0)
      { t: 'txt', p: 'HELLO' }, // write at start of line
    ]);

    const line = snapshot(buf)[0];
    // "HELLO" should be at the START of the line (col 0-4), not missing its first char
    expect(line.startsWith('HELLO')).toBe(true);
    // The line should NOT be "ELLO" (missing first char due to cx=-1)
    expect(line.startsWith('ELLO')).toBe(false);
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 9: Zero-value CUP row/col treated as defaults
  // ──────────────────────────────────────────────────────────────────────────

  it('CUP with zero row defaults to row 1', () => {
    buf.resize(80);
    // CUP(0, 5) — row 0 should mean row 1 (cy=0), col 5 means cx=4
    buf.applyEvents([
      { t: 'H', p: [0, 5] },
      { t: 'txt', p: 'X' },
    ]);
    const line = snapshot(buf)[0];
    const xPos = line.indexOf('X');
    expect(xPos).toBe(4); // 0-indexed column 4
  });

  it('bare VPA \\x1b[d defaults to row 1, not -1', () => {
    buf.resize(80);
    buf.applyEvents([
      { t: 'd', p: 0 },       // VPA 0 → should go to row 1 (cy=0)
      { t: 'txt', p: 'TOP' },
    ]);
    const line0 = snapshot(buf)[0];
    expect(line0).toContain('TOP');
  });

  // ──────────────────────────────────────────────────────────────────────────
  // Scenario 10: Real Claude output through applyEvents (NOT write)
  //   The e2e tests use buf.write() which bypasses the applyEvents → putChar
  //   path. This test feeds the actual raw bytes through the Rust parser
  //   equivalent (pre-parsed events) to verify the real code path.
  // ──────────────────────────────────────────────────────────────────────────

  it('real Claude events through applyEvents do not lose first char after CHA', () => {
    // Simulate the exact event pattern Claude generates:
    // \x1b[2G Bold "Accessing" \x1b[12G "workspace:" \x1b[22m \x1b[39m \r\n
    buf.resize(80);
    buf.applyEvents([
      { t: 'm', p: [1, 38, 5, 220] }, // bold + yellow
      { t: 'G', p: 2 },                 // CHA to col 2
      { t: 'txt', p: 'Accessing' },
      { t: 'G', p: 12 },                // CHA to col 12
      { t: 'txt', p: 'workspace:' },
      { t: 'm', p: [22] },              // normal
      { t: 'm', p: [39] },              // default fg
      { t: 'cr' },
      { t: 'lf' },
      // Now the critical sequence:
      { t: 'K', p: 2 },                 // EraseLine(2) — clear entire line
      { t: 'G', p: 0 },                 // BARE CHA — should move to col 1! (THIS IS THE BUG)
      { t: 'A', p: 1 },                 // Cuu — move up
      // Write text on that line
      { t: 'txt', p: 'Claude Code' },
    ]);

    const lines = snapshot(buf);
    // Find the line with "Claude Code"
    const ccLine = lines.find(l => l.includes('Claude Code'));
    expect(ccLine).toBeDefined();
    // Line should NOT start with "laude Code" (missing first char)
    if (ccLine) {
      const idx = ccLine.indexOf('Claude Code');
      expect(idx).not.toBe(-1);
      const before = ccLine.substring(0, idx).trim();
      // Should NOT have partial text before "Claude Code" from lost char
      expect(before).toBe('');
    }
  });
});
